import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Read the diagnostic panel","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/debugging.md","filePath":"en/guides/debugging.md","lastUpdated":1794405696000}`),a={name:`en/guides/debugging.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="read-the-diagnostic-panel" tabindex="-1">Read the diagnostic panel <a class="header-anchor" href="#read-the-diagnostic-panel" aria-label="Permalink to “Read the diagnostic panel”">​</a></h1><p>Find out &quot;why it was displayed&quot; or &quot;why it isn&#39;t displayed&quot; in the browser you are actually using. You need edit permission for the site.</p><h2 id="how-to-open-it" tabindex="-1">How to open it <a class="header-anchor" href="#how-to-open-it" aria-label="Permalink to “How to open it”">​</a></h2><p>In &quot;Verification (「動作確認」)&quot; in the admin console, enter the target URL and start diagnostics on the real site. Keep both the site with the SDK and the admin console open.</p><p>A temporary panel appears on the site. No browser extension is needed. The authorization is limited to the site and origin, and is valid for 15 minutes. No admin token or passkey information is passed to the site.</p><h2 id="what-you-can-see" tabindex="-1">What you can see <a class="header-anchor" href="#what-you-can-see" aria-label="Permalink to “What you can see”">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Contents</th></tr></thead><tbody><tr><td>Current state</td><td>Consent, measurement, display time, the current page and so on</td></tr><tr><td>Browsing and actions</td><td>Pages observed in this browser, where information was taken from, additional events and states</td></tr><tr><td>Judgment history</td><td>Decision API requests and responses, state/questions for Jev, scores, confirmed conditions and display constraints</td></tr></tbody></table><p>History is not saved on the server for diagnostics. The panel observes normal API requests, and opening it doesn&#39;t trigger an extra Jev request. Diagnostics don&#39;t bypass consent either.</p><h2 id="how-to-read-why-it-isn-t-displayed" tabindex="-1">How to read why it isn&#39;t displayed <a class="header-anchor" href="#how-to-read-why-it-isn-t-displayed" aria-label="Permalink to “How to read why it isn&#39;t displayed”">​</a></h2><ul><li><strong>Metadata sending is not approved</strong>: check whether you enabled sending in the site settings.</li><li><strong>Not enough valid views</strong>: check the display time and the count. Time in a background tab is not counted as display time.</li><li><strong>Outside the target pages</strong>: check the collected range and the campaign&#39;s display targets separately.</li><li><strong>Already displayed or closed</strong>: check the limit and state in this browser.</li><li><strong>Confirmed state is unknown</strong>: if you specified an excluded fact, pass false/true explicitly.</li><li><strong>The score is too low</strong>: check the question and the threshold. Don&#39;t read the score as a purchase rate.</li><li><strong>Model error or cost limit</strong>: the operator checks the key, model and limit.</li></ul><h2 id="preview-test-values" tabindex="-1">Preview test values <a class="header-anchor" href="#preview-test-values" aria-label="Permalink to “Preview test values”">​</a></h2><p>In the stub environment, it is labeled &quot;Judged with a fixed test value&quot; and &quot;Not sent to Jev&quot;. The 0.95 here is not output from the real model. Don&#39;t treat it as a measurement of usage or speed.</p><h2 id="when-you-share-it" tabindex="-1">When you share it <a class="header-anchor" href="#when-you-share-it" aria-label="Permalink to “When you share it”">​</a></h2><p>Requests and screens contain page information and behavior information. Before sharing a screenshot or JSON, check that it contains no personal information, confidential information or credentials. Don&#39;t paste real browsing history as it is into ordinary Issues.</p><p>Close diagnostics with the end button. Authorization is also lost when a user is disabled or site permission is revoked. Simply signing out does not individually clear an already issued diagnostic authorization.</p><h2 id="telling-the-initial-decision-from-local-updates" tabindex="-1">Telling the initial decision from local updates <a class="header-anchor" href="#telling-the-initial-decision-from-local-updates" aria-label="Permalink to “Telling the initial decision from local updates”">​</a></h2><p>The current page, the entry page and past valid views are shown separately. The initial decision for a page happens only once. Reaching the minimum viewing time is recorded as &quot;Saved to valid views (no communication)&quot;, and the integration of events and states is also recorded as a local update. In the judgment history, check the JSON and the response at the time of the request.</p><p>If the diagnostic connection wasn&#39;t ready in time for the initial decision, the details of that request are not recovered afterward. Move to the next page and check its initial decision. No extra Jev request is made to open the panel.</p><h2 id="the-browsing-and-actions-timeline" tabindex="-1">The browsing and actions timeline <a class="header-anchor" href="#the-browsing-and-actions-timeline" aria-label="Permalink to “The browsing and actions timeline”">​</a></h2><p>The upper part of &quot;Browsing and actions&quot; shows the history of actions from entry to now. It starts oldest first, and you can switch to newest first. A page card shows its name, path and display time, and &quot;Fetched page information&quot; opens the details. The current page is highlighted in green to distinguish it from past valid views.</p><p>Allowed actions and state changes integrated during diagnostics appear between page views in time order. Revisiting the same page counts as a separate view. The lower &quot;Other measurement information&quot; section gathers where the current page&#39;s information came from, the actions and states being held, and each campaign&#39;s display count and closed state.</p><p>After a reload, the saved entry page and past valid views are shown. Times that weren&#39;t saved are shown as &quot;No time recorded&quot;, and pages in between that were shorter than the minimum viewing time and the times of past actions are not guessed or filled in. Times and short views from during diagnostics are kept only inside the existing diagnostic buffer (up to 60 items and 1 MB in total), and are erased on consent withdrawal, ending, expiry and a normal reload. No diagnostic times or view IDs are added to storage or API requests.</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};